import{_ as a,o as i,c as e,ah as t}from"./chunks/framework.DV4RPuBi.js";const k=JSON.parse('{"title":"创建新项目","description":"","frontmatter":{},"headers":[],"relativePath":"sop/create-project.md","filePath":"sop/create-project.md","lastUpdated":1786017778000}'),l={name:"sop/create-project.md"};function n(h,s,p,r,o,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="创建新项目" tabindex="-1">创建新项目 <a class="header-anchor" href="#创建新项目" aria-label="Permalink to &quot;创建新项目&quot;">​</a></h1><h2 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fe-harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-h5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fe-harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-h5</span></span></code></pre></div><p>离线创建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fe-harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-h5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-install</span></span></code></pre></div><h2 id="会生成什么" tabindex="-1">会生成什么 <a class="header-anchor" href="#会生成什么" aria-label="Permalink to &quot;会生成什么&quot;">​</a></h2><p>Consumer H5 preset 会生成：</p><ul><li>uni-app + Vue 3 + Vite 基础项目。</li><li>Playwright runtime/visual 验证配置。</li><li><code>.fe-harness/project.yaml</code>。</li><li><code>.fe-harness/inputs/</code> 标准输入目录。</li><li><code>AGENTS.md</code>、<code>CLAUDE.md</code>、Cursor rule。</li><li>默认聚合 Skill：<code>consumer-h5-harness</code>。</li><li>docs 下的 PRODUCT、DESIGN、CURRENT_STATUS、PROJECT_MAP、history 和 coverage 文件。</li><li>src 下的 components、services、repositories、stores、utils 等边界目录。</li></ul><h2 id="为什么不在创建前要求-prd-ui-api" tabindex="-1">为什么不在创建前要求 PRD/UI/API <a class="header-anchor" href="#为什么不在创建前要求-prd-ui-api" aria-label="Permalink to &quot;为什么不在创建前要求 PRD/UI/API&quot;">​</a></h2><p>创建项目的目标是生成容器和规则，不是立刻完成业务。真实项目经常会出现输入暂时不完整的情况。如果在创建阶段强行要求所有材料齐备，会让脚手架变成流程阻塞。</p><p>正确做法是：</p><ol><li>先创建项目和输入目录。</li><li>把已有材料放入 <code>.fe-harness/inputs/</code>。</li><li>再登记、分析和创建首个任务。</li></ol><h2 id="默认只安装聚合-skill" tabindex="-1">默认只安装聚合 Skill <a class="header-anchor" href="#默认只安装聚合-skill" aria-label="Permalink to &quot;默认只安装聚合 Skill&quot;">​</a></h2><p>新项目默认只安装 <code>consumer-h5-harness</code>。命令级 Skills 仍可按需安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fe-harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fe-harness-api</span></span></code></pre></div><p>这样做是为了减少默认上下文。普通业务任务不需要一开始就加载 OpenAPI、Design Token、UI System、视觉基线等深层规则。</p>`,16)])])}const u=a(l,[["render",n]]);export{k as __pageData,u as default};
